type Greeter interface {
    Greet() string
}

type Developer struct{ Name string }

// Erfüllt das Interface 'Greeter' implizit
func (d Developer) Greet() string {
    return "Hallo, ich bin " + d.Name
}

func printValue(val any) {
    switch v := val.(type) {
    case int:
        fmt.Printf("Ganzzahl: %d\n", v)
    case string:
        fmt.Printf("Text: %s\n", v)
    default:
        fmt.Println("Unbekannter Typ")
    }
}

