sections.solutionCode:
package main

import "fmt"

type Logger interface {
    Log(msg string) error
}

type ConsoleLogger struct{}

// Korrekt: Gibt error zurück (nil bei Erfolg)
func (c ConsoleLogger) Log(msg string) error {
    fmt.Println(msg)
    return nil
}

func Run(l Logger) {
    l.Log("System gestartet")
}
